def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    adj = [0] * n
    deg = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1; v = int(data[idx + 1]) - 1; idx += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u
        deg[u] += 1
        deg[v] += 1

    mat = [adj[i] for i in range(n) if deg[i] > 0]
    rows_count = len(mat)

    pivot_cols = []
    r = 0
    for col in range(n):
        sel = -1
        for i in range(r, rows_count):
            if (mat[i] >> col) & 1:
                sel = i
                break
        if sel < 0:
            continue
        mat[r], mat[sel] = mat[sel], mat[r]
        for i in range(rows_count):
            if i != r and ((mat[i] >> col) & 1):
                mat[i] ^= mat[r]
        pivot_cols.append(col)
        r += 1
        if r == rows_count:
            break

    pivot_set = set(pivot_cols)
    basis = []
    for f in range(n):
        if f in pivot_set:
            continue
        vec = 1 << f
        for i in range(r):
            if (mat[i] >> f) & 1:
                vec |= 1 << pivot_cols[i]
        basis.append(vec)

    covered = 0
    for b in basis:
        covered |= b
    if covered != (1 << n) - 1:
        print("No")
        return

    res = []
    for v in range(n):
        x = 0
        for j, b in enumerate(basis):
            if (b >> v) & 1:
                x |= 1 << j
        res.append(x)
    print("Yes")
    print(' '.join(map(str, res)))

