def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    P = [int(x) - 1 for x in data[1:1 + n]]
    A = [int(x) for x in data[1 + n:1 + 2 * n]]

    spf = list(range(n + 1))
    i = 2
    while i * i <= n:
        if spf[i] == i:
            spf[i * i::i] = [i] * ((n - i * i) // i + 1)
        i += 1

    ans = [0] * n
    visited = [False] * n
    pw = {}
    Rmod = {}

    for start in range(n):
        if visited[start]:
            continue
        cyc = []
        j = start
        while not visited[j]:
            visited[j] = True
            cyc.append(j)
            j = P[j]
        L = len(cyc)
        v = [A[c] for c in cyc]

        fl = {}
        x = L
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            fl[p] = e

        g = 1
        parts = []
        for p, f in fl.items():
            e = pw.get(p, 0)
            m = e if e < f else f
            if m > 0:
                pm = p ** m
                g *= pm
                parts.append((pm, Rmod[p] % pm))

        if parts:
            r0, mm = parts[0]
            for a2, m2 in parts[1:]:
                t = (a2 - r0) * pow(mm, -1, m2) % m2
                r0 += mm * t
                mm *= m2
        else:
            r0 = 0

        best_r = r0
        best_val = v[r0]
        for idx in range(r0 + g, L, g):
            val = v[idx]
            if val < best_val:
                best_val = val
                best_r = idx
        r = best_r

        w = v[r:] + v[:r]
        for c, val in zip(cyc, w):
            ans[c] = val

        for p, f in fl.items():
            if f > pw.get(p, 0):
                pw[p] = f
                Rmod[p] = r % (p ** f)

    print(' '.join(map(str, ans)))

