class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        import heapq
        heap = []  # max-heap (via negatives) holding the k smallest distances seen so far
        res = []
        for x, y in queries:
            d = abs(x) + abs(y)
            heapq.heappush(heap, -d)
            if len(heap) > k:
                heapq.heappop(heap)
            res.append(-heap[0] if len(heap) == k else -1)
        return res

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def variants(x):
            s = str(x)
            res = {x}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    lst = list(s)
                    lst[i], lst[j] = lst[j], lst[i]
                    res.add(int(''.join(lst)))
            return res

        vs = [variants(x) for x in nums]
        n = len(nums)
        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] in vs[i] or nums[i] in vs[j]:
                    count += 1
        return count

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        from collections import defaultdict

        n = len(grid)
        # For each distinct value, list the rows that contain it
        rows_with = defaultdict(list)
        for r, row in enumerate(grid):
            for v in set(row):
                rows_with[v].append(r)

        NEG = float('-inf')
        # dp[mask] = max score using exactly the rows in mask
        dp = [NEG] * (1 << n)
        dp[0] = 0

        for v, rlist in rows_with.items():
            ndp = dp[:]  # option: skip this value entirely
            for mask in range(1 << n):
                if dp[mask] == NEG:
                    continue
                base = dp[mask] + v
                for r in rlist:
                    if not (mask >> r) & 1:
                        nm = mask | (1 << r)
                        if base > ndp[nm]:
                            ndp[nm] = base
            dp = ndp

        # values are positive, so the maximum always selects at least one cell
        return max(dp)

