class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()
        n = len(start)
        s = start
        last = s[-1] + d - s[0]

        def feasible(x: int) -> bool:
            prev = s[0]
            for i in range(1, n):
                nxt = prev + x
                if s[i] > nxt:
                    nxt = s[i]
                if nxt > s[i] + d:
                    return False
                prev = nxt
            return True

        lo, hi = 0, last
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

