class Solution:
    def maxScore(self, a: List[int], b: List[int]) -> int:
        NEG = float('-inf')
        dp = [0, NEG, NEG, NEG, NEG]
        for x in b:
            for k in (4, 3, 2, 1):
                cand = dp[k - 1] + a[k - 1] * x
                if cand > dp[k]:
                    dp[k] = cand
        return dp[4]

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        # cnt[i] = length of the strictly consecutive ascending run ending at i
        cnt = [1] * n
        for i in range(1, n):
            if nums[i] == nums[i - 1] + 1:
                cnt[i] = cnt[i - 1] + 1

        res = []
        for i in range(n - k + 1):
            if cnt[i + k - 1] >= k:
                # Window is consecutive & ascending, so last element is the max
                res.append(nums[i + k - 1])
            else:
                res.append(-1)
        return res

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        # Key insight: only the top-3 cells of each row can ever be used,
        # since at most 2 other columns are blocked by the other two rooks.
        candidates = []
        for i, row in enumerate(board):
            top_cols = sorted(range(len(row)), key=lambda j: -row[j])[:3]
            for j in top_cols:
                candidates.append((row[j], i, j))
        # Sort descending by value to enable pruning
        candidates.sort(key=lambda x: -x[0])
        n = len(candidates)
        best = float('-inf')
        for a in range(n):
            va, ra, ca = candidates[a]
            if 3 * va <= best:
                break
            for b in range(a + 1, n):
                vb, rb, cb = candidates[b]
                if rb == ra or cb == ca:
                    continue
                if va + 2 * vb <= best:
                    break
                for c in range(b + 1, n):
                    vc, rc, cc = candidates[c]
                    if va + vb + vc <= best:
                        break
                    if rc == ra or rc == rb or cc == ca or cc == cb:
                        continue
                    s = va + vb + vc
                    if s > best:
                        best = s
        return best

class Solution:
    def generateKey(self, num1: int, num2: int, num3: int) -> int:
        key = 0
        for p in (1000, 100, 10, 1):
            d1 = (num1 // p) % 10
            d2 = (num2 // p) % 10
            d3 = (num3 // p) % 10
            key = key * 10 + min(d1, d2, d3)
