class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        max_len = [0] * n  # max_len[i]: longest prefix of any word matching target starting at i

        def zfunc(s):
            m = len(s)
            z = [0] * m
            l = r = 0
            for i in range(1, m):
                zi = 0
                if i < r:
                    zi = z[i - l]
                    rem = r - i
                    if zi > rem:
                        zi = rem
                while i + zi < m and s[zi] == s[i + zi]:
                    zi += 1
                z[i] = zi
                if i + zi > r:
                    l = i
                    r = i + zi
            return z

        for w in words:
            start = len(w) + 1
            z = zfunc(w + '\x00' + target)
            tail = z[start:]
            max_len = [b if b > a else a for a, b in zip(max_len, tail)]

        INF = float('inf')
        # dp is non-decreasing: truncating the last segment of a decomposition keeps validity,
        # so dp[i] = 1 + dp[j*] where j* is the smallest j < i with j + max_len[j] >= i.
        dp = [INF] * (n + 1)
        dp[0] = 0
        p = 0
        for i in range(1, n + 1):
            while p < i and p + max_len[p] < i:
                p += 1
            if p < i:
                dp[i] = dp[p] + 1

        return dp[n] if dp[n] != INF else -1

class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        need = [0] * 26
        for ch in word2:
            need[ord(ch) - 97] += 1

        cnt = [0] * 26
        missing = sum(1 for x in need if x > 0)  # chars whose count is still short
        ans = 0
        left = 0
        n = len(word1)

        for right in range(n):
            idx = ord(word1[right]) - 97
            cnt[idx] += 1
            if cnt[idx] == need[idx]:
                missing -= 1

            while missing == 0:
                lidx = ord(word1[left]) - 97
                cnt[lidx] -= 1
                if cnt[lidx] < need[lidx]:
                    missing += 1
                left += 1

            ans += left

        return ans

