class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        vowels = set('aeiou')
        total = 0
        for i in range(n):
            seen = set()
            cons = 0
            for j in range(i, n):
                c = word[j]
                if c in vowels:
                    seen.add(c)
                else:
                    cons += 1
                    if cons > k:
                        break
                if cons == k and len(seen) == 5:
                    total += 1
        return total

class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        arr = sorted(maximumHeight, reverse=True)
        total = 0
        cur = arr[0]
        total += cur
        for h in arr[1:]:
            cur = min(cur - 1, h)
            if cur < 1:
                return -1
            total += cur
        return total

class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        def z_function(t):
            n = len(t)
            z = [0] * n
            l = r = 0
            for i in range(1, n):
                zi = min(r - i, z[i - l]) if i < r else 0
                while i + zi < n and t[zi] == t[i + zi]:
                    zi += 1
                z[i] = zi
                if i + zi > r:
                    l, r = i, i + zi
            return z

        n, m = len(s), len(pattern)
        z1 = z_function(pattern + '#' + s)                 # forward prefix matches
        z2 = z_function(pattern[::-1] + '#' + s[::-1])     # suffix matches via reversal

        for i in range(n - m + 1):
            a = z1[m + 1 + i]                    # LCP of s[i:] and pattern (<= m)
            b = z2[m + 1 + (n - i - m)]          # common suffix of s[:i+m] and pattern (<= m)
            if a + b >= m - 1:
                return i
        return -1

