from typing import List
from bisect import bisect_left

class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)

        # t0[i] = max number of trailing characters of word2 that can be
        # matched exactly (no change) as a subsequence of word1[i:]
        t0 = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            k = t0[i + 1]
            if k < m and word1[i] == word2[m - 1 - k]:
                t0[i] = k + 1
            else:
                t0[i] = k

        # occurrences of each character in word1 (sorted indices)
        occ = [[] for _ in range(26)]
        for idx, c in enumerate(word1):
            occ[ord(c) - 97].append(idx)

        res = []
        pos = 0
        used = False
        for j in range(m):
            if pos >= n:
                return []
            c = word2[j]
            o = occ[ord(c) - 97]
            t = bisect_left(o, pos)
            has_eq = t < len(o)

            if not used:
                if word1[pos] == c:
                    # earliest exact match is always safe (exchange argument)
                    res.append(pos)
                    pos += 1
                elif t0[pos + 1] >= m - j - 1:
                    # spend the single change at the earliest possible index;
                    # the rest must then match exactly, which t0 guarantees
                    res.append(pos)
                    used = True
                    pos += 1
                elif has_eq:
                    # change at pos (or any earlier non-exact spot) is infeasible,
                    # so jump to the earliest exact occurrence
                    res.append(o[t])
                    pos = o[t] + 1
                else:
                    return []
            else:
                if has_eq:
                    res.append(o[t])
                    pos = o[t] + 1
                else:
                    return []

        return res

