from collections import deque

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1]); S = data[2]
    MOD = 998244353
    sc = [ord(ch) - 97 for ch in S]

    def step(dp, c):
        ndp = [0] * (N + 1)
        prev = 0
        for j in range(1, N + 1):
            v = dp[j - 1] + (1 if sc[j - 1] == c else 0)
            if dp[j] > v:
                v = dp[j]
            if prev > v:
                v = prev
            prev = v
            ndp[j] = v
        return tuple(ndp)

    init = (0,) * (N + 1)
    states = {init: 0}
    state_list = [init]
    raw = []
    q = deque([init])
    while q:
        st = q.popleft()
        row = []
        for c in range(26):
            ns = step(st, c)
            nid = states.get(ns, -1)
            if nid < 0:
                nid = len(state_list)
                states[ns] = nid
                state_list.append(ns)
                q.append(ns)
            row.append(nid)
        raw.append(row)

    num = len(state_list)
    trans = []
    for row in raw:
        d = {}
        for nid in row:
            d[nid] = d.get(nid, 0) + 1
        trans.append(list(d.items()))

    cnt = [0] * num
    cnt[0] = 1
    for _ in range(M):
        ncnt = [0] * num
        for sid in range(num):
            v = cnt[sid]
            if v:
                for nid, w in trans[sid]:
                    ncnt[nid] = (ncnt[nid] + v * w) % MOD
        cnt = ncnt

    ans = [0] * (N + 1)
    for sid in range(num):
        k = state_list[sid][N]
        ans[k] = (ans[k] + cnt[sid]) % MOD

    print(' '.join(map(str, ans)))

