    pot = [0] * (N + 1)
    sz = [1] * (N + 1)

    def find(v):
        path = []
        while parent[v] != v:
            path.append(v)
            v = parent[v]
        root = v
        for node in reversed(path):
            pot[node] ^= pot[parent[node]]
            parent[node] = root
        return root

    ptr = 2
    for _ in range(M):
        x = data[ptr]; y = data[ptr + 1]; z = data[ptr + 2]
        ptr += 3
        rx = find(x); ry = find(y)
        if rx == ry:
            if pot[x] ^ pot[y] != z:
                print(-1)
                return
        else:
            w = pot[x] ^ pot[y] ^ z
            if sz[rx] >= sz[ry]:
                parent[ry] = rx; pot[ry] = w; sz[rx] += sz[ry]
            else:
                parent[rx] = ry; pot[rx] = w; sz[ry] += sz[rx]

    roots = [find(v) for v in range(N + 1)]

    try:
        import numpy as np
    except ImportError:
        np = None

    if np is not None:
        P = np.array(pot, dtype=np.int64)
        R = np.array(roots, dtype=np.intp)
        sizes = np.bincount(R, minlength=N + 1)
        r = np.zeros(N + 1, dtype=np.int64)
        for b in range(30):
            mask = ((P >> b) & 1).astype(bool)
            cnt = np.bincount(R[mask], minlength=N + 1)
            flip = cnt * 2 > sizes
            r[flip] |= (1 << b)
        A = r[R] ^ P
        sys.stdout.write(' '.join(map(str, A[1:].tolist())) + '\n')
    else:
        from collections import defaultdict
        comp = defaultdict(list)
        for v in range(1, N + 1):
            comp[roots[v]].append(v)
        ans = [0] * (N + 1)
        for rt, vs in comp.items():
            n = len(vs)
            pots = [pot[v] for v in vs]
            r = 0
            for b in range(30):
                c = 0
                for x in pots:
                    c += (x >> b) & 1
                if 2 * c > n:
                    r |= 1 << b
            for v in vs:
                ans[v] = r ^ pot[v]
        sys.stdout.write(' '.join(map(str, ans[1:])) + '\n')

