import sys, random
from math import gcd, isqrt

def main():
    data = sys.stdin.buffer.read().split()
    T = int(data[0])
    LIM = 1000
    sieve = bytearray([1]) * (LIM + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, isqrt(LIM) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, LIM + 1, i)))
    SP = [i for i in range(2, LIM + 1) if sieve[i]]

    def is_prime(n):
        for p in (2,3,5,7):
            if n % p == 0: return n == p
        d = n - 1; s = 0
        while not d & 1: d >>= 1; s += 1
        for a in (2,3,5,7):
            x = pow(a, d, n)
            if x == 1 or x == n-1: continue
            for _ in range(s-1):
                x = x * x % n
                if x == n-1: break
            else: return False
        return True

    def pollard(n):
        while True:
            c = random.randrange(1, n); y = random.randrange(0, n)
            g = r = q = 1; x = ys = y
            while g == 1:
                x = y
                for _ in range(r): y = (y*y + c) % n
                k = 0
                while k < r and g == 1:
                    ys = y
                    for _ in range(min(128, r-k)):
                        y = (y*y + c) % n
                        q = q * (x - y) % n
                    g = gcd(q, n); k += 128
                r <<= 1
            if g == n:
                g = 1
                while g == 1:
                    ys = (ys*ys + c) % n
                    g = gcd(x - ys, n)
                if g == n: continue
            return g

    def factorize(n):
        f = []
        for p in SP:
            if p * p > n: break
            if n % p == 0:
                e = 1; n //= p
                while n % p == 0: n //= p; e += 1
                f.append((p, e))
        if n > 1:
            if n < 1018081:  # 1009^2: all remaining factors >= 1009 -> prime
                f.append((n, 1))
            else:
                s = isqrt(n)
                if s * s == n: f.append((s, 2))
                elif is_prime(n): f.append((n, 1))
                else:
                    d = pollard(n)
                    f.append((d, 1)); f.append((n // d, 1))
        return f

    fcache = {}
    out = []
    for idx in range(1, T + 1):
        N = int(data[idx])
        if N == 1:
            out.append("1 1"); continue
        if N in fcache: f = fcache[N]
        else:
            f = factorize(N); fcache[N] = f
        residues = []; moduli = []
        two_e = 0
        for p, e in f:
            if p == 2: two_e = e
        if two_e == 1:
            moduli.append(4); residues.append(3)
        elif two_e >= 2:
            moduli.append(1 << (two_e + 2)); residues.append(5)
        for p, e in f:
            if p == 2: continue
            moduli.append(p ** (e + 1)); residues.append(p + 1)
        A = residues[0]; M = moduli[0]
        for j in range(1, len(moduli)):
            m1 = moduli[j]
            t = (residues[j] - A) * pow(M, -1, m1) % m1
            A += M * t
            M *= m1
        out.append(str(A) + " " + str(M))
    sys.stdout.write("\n".join(out) + "\n")

