class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        # Build the full zigzag order: even rows left->right, odd rows right->left.
        # Skip parity is global over the whole traversal, so flatten first, then
        # take every other element starting at index 0.
        order = []
        for i, row in enumerate(grid):
            if i % 2 == 0:
                order.extend(row)
            else:
                order.extend(row[::-1])
        return order[::2]

class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
        total = 0
        for i in range(n):
            start = max(0, i - nums[i])
            total += pre[i + 1] - pre[start]
        return total

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        # diff = leftSum - rightSum = total - 2 * rightSum
        # So diff parity always equals total parity: all or nothing.
        return len(nums) - 1 if sum(nums) % 2 == 0 else 0

