class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # online_at[u] = earliest time user u is (back) online; 0 means always online so far
        online_at = [0] * numberOfUsers

        # Sort by timestamp; OFFLINE before MESSAGE at the same timestamp,
        # so status changes are applied before same-time messages.
        ordered = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for ev in ordered:
            typ, ts, data = ev
            t = int(ts)
            if typ == "OFFLINE":
                online_at[int(data)] = t + 60
            else:
                if data == "ALL":
                    for u in range(numberOfUsers):
                        mentions[u] += 1
                elif data == "HERE":
                    for u in range(numberOfUsers):
                        if online_at[u] <= t:  # online at time t (comeback processed first)
                            mentions[u] += 1
                else:
                    for token in data.split():
                        mentions[int(token[2:])] += 1  # strip "id" prefix; duplicates count

        return mentions

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        for d in range(-(n - 1), n):
            i, j = max(0, d), max(0, -d)
            cells = []
            while i < n and j < n:
                cells.append(grid[i][j])
                i += 1
                j += 1
            if d >= 0:
                cells.sort(reverse=True)  # bottom-left + middle: non-increasing
            else:
                cells.sort()              # top-right: non-decreasing
            i, j, k = max(0, d), max(0, -d), 0
            while i < n and j < n:
                grid[i][j] = cells[k]
                i += 1
                j += 1
                k += 1
        return grid

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        t = k + 1

        def f(X, Y):
            # number of (x, y): 1<=x<=X, 1<=y<=Y, x+y <= t  (subarray length x+y-1 <= k)
            Xc = min(X, t - 1)
            if Xc <= 0:
                return 0
            A = min(Xc, t - Y - 1)
            part1 = A * Y if A > 0 else 0
            B = max(1, t - Y)
            if B <= Xc:
                cnt = Xc - B + 1
                part2 = cnt * t - (B + Xc) * cnt // 2
            else:
                part2 = 0
            return part1 + part2

        def total(pop_left, pop_right):
            L = [-1] * n
            R = [n] * n
            st = []
            for i in range(n):
                v = nums[i]
                while st and pop_left(nums[st[-1]], v):
                    st.pop()
                L[i] = st[-1] if st else -1
                st.append(i)
            st = []
            for i in range(n - 1, -1, -1):
                v = nums[i]
                while st and pop_right(nums[st[-1]], v):
                    st.pop()
                R[i] = st[-1] if st else n
                st.append(i)
            s = 0
            for i in range(n):
                s += nums[i] * f(i - L[i], R[i] - i)
            return s

        # max: previous >= on left (pop while <), next > on right (pop while <=)
        # min: previous <= on left (pop while >), next < on right (pop while >=)
        return (total(lambda a, b: a < b, lambda a, b: a <= b)
                + total(lambda a, b: a > b, lambda a, b: a >= b))

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        # Manhattan(x, y) = max over signs (sx, sy) of sx*x + sy*y.
        # For a fixed quadrant (sx, sy), each character contributes +1 or -1
        # to the projection. A -1 contributor can be changed (1 change) into
        # a +1 contributor, gaining 2 per flip. So the best projection at
        # prefix t is p - n + 2*min(n, k) where p/n are +/-1 counts in prefix t.
        ans = 0
        for sx, sy in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
            cur = 0   # unflipped prefix sum of contributions
            neg = 0   # count of -1 contributions so far
            for c in s:
                if c == 'N':
                    v = sy
                elif c == 'S':
                    v = -sy
                elif c == 'E':
                    v = sx
                else:  # 'W'
                    v = -sx
                if v > 0:
                    cur += 1
                else:
                    cur -= 1
                    neg += 1
                cand = cur + 2 * min(neg, k)
                if cand > ans:
                    ans = cand
        return ans

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        # A valid substring of length k must be a maximal run of exactly length k:
        # if the run were longer, one neighbor inside the run would match.
        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if j - i == k:
                return True
            i = j
        return False

