class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        # Gather candidates: top limits[i] elements from each row.
        # Since all values are non-negative, an optimal solution only ever
        # uses elements from this candidate pool.
        candidates = []
        for row, lim in zip(grid, limits):
            if lim > 0:
                candidates.extend(heapq.nlargest(lim, row))
        # Take the top k from the candidate pool (k <= len(candidates) guaranteed).
        return sum(heapq.nlargest(k, candidates))

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1
        # Iterative max segment tree; 0 marks an used basket (capacities >= 1)
        tree = [0] * (2 * size)
        for i, c in enumerate(baskets):
            tree[size + i] = c
        for i in range(size - 1, 0, -1):
            tree[i] = tree[2 * i] if tree[2 * i] >= tree[2 * i + 1] else tree[2 * i + 1]

        unplaced = 0
        for f in fruits:
            if tree[1] < f:
                unplaced += 1
                continue
            # Descend to leftmost leaf with value >= f
            i = 1
            while i < size:
                i <<= 1
                if tree[i] < f:
                    i += 1
            tree[i] = 0  # consume this basket
            i >>= 1
            while i:
                l, r = tree[2 * i], tree[2 * i + 1]
                tree[i] = l if l >= r else r
                i >>= 1
        return unplaced

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Group pairs by their right endpoint (max of the two values)
        groups = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            lo, hi = (a, b) if a < b else (b, a)
            groups[hi].append((lo, i))

        m = len(conflictingPairs)
        gain = [0] * m

        # Track the two largest left-boundary constraints (min values) among
        # pairs whose max <= current r, along with which pair provides each.
        best1_val, best1_idx = 0, -1
        best2_val, best2_idx = 0, -1

        total = 0
        for r in range(1, n + 1):
            for lo, i in groups[r]:
                if lo > best1_val:
                    best2_val, best2_idx = best1_val, best1_idx
                    best1_val, best1_idx = lo, i
                elif lo > best2_val:
                    best2_val, best2_idx = lo, i

            # If the top constraint is strictly unique, removing that pair
            # relaxes the left boundary from best1 to best2 for this r.
            if best1_val > best2_val:
                gain[best1_idx] += best1_val - best2_val

            total += r - best1_val

        return total + max(gain)

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        pos = defaultdict(list)
        for i, v in enumerate(nums):
            pos[v].append(i)  # indices appended in increasing order

        res = {}
        for g in pos.values():
            m = len(g)
            if m < 2:
                continue
            for p in range(m):
                i = g[p]
                a = g[(p - 1) % m]
                b = g[(p + 1) % m]
                d1 = abs(i - a)
                d1 = min(d1, n - d1)
                d2 = abs(i - b)
                d2 = min(d2, n - d2)
                res[i] = min(d1, d2)

        return [res.get(q, -1) for q in queries]

