class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Deletions let any subsequence become a contiguous subarray,
        # so the best choice is: take every distinct positive value once.
        # If no positive value exists, we must still pick one element -> the maximum.
        total = sum(v for v in set(nums) if v > 0)
        return total if total > 0 else max(nums)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        sets = [set(row) for row in properties]

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    ri, rj = find(i), find(j)
                    if ri != rj:
                        parent[ri] = rj

        return len({find(i) for i in range(n)})

