        return sorted(x % 2 for x in nums)

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # copy is fully determined by copy[0] = x: copy[i] = x + original[i] - original[0]
        # Constraint: u_i <= x + original[i] - original[0] <= v_i
        # => x in [u_i - original[i] + original[0], v_i - original[i] + original[0]]
        # Intersect over all i (constant original[0] shift cancels in the width).
        lo = max(u - o for o, (u, _) in zip(original, bounds))
        hi = min(v - o for o, (_, v) in zip(original, bounds))
        return max(0, hi - lo + 1)

