class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)

        # palStartS[i]: longest palindromic substring of s starting at index i (palStartS[n] = 0)
        palStartS = [0] * (n + 1)
        for i in range(n):
            for j in range(i, n):
                sub = s[i:j + 1]
                if sub == sub[::-1]:
                    palStartS[i] = j - i + 1

        # palEndT[e+1]: longest palindromic substring of t ending at index e (palEndT[0] = 0 for e = -1)
        palEndT = [0] * (m + 1)
        for e in range(m):
            for st in range(e, -1, -1):
                sub = t[st:e + 1]
                if sub == sub[::-1]:
                    palEndT[e + 1] = e - st + 1
                    break

        # Single-string palindromes (covers empty counterpart cases)
        ans = max(max(palStartS), max(palEndT))

        # Crossing palindromes: P = A + B with A = s[x1..], B = t[..y2]
        # match: s[x1+u] == t[y2-u] for u < k
        for x1 in range(n):
            for y2 in range(m):
                k = 0
                while k < n - x1 and k <= y2 and s[x1 + k] == t[y2 - k]:
                    k += 1
                for b in range(1, k + 1):
                    # A = reverse(B) + M, M palindrome in s starting at x1+b
                    c1 = 2 * b + palStartS[x1 + b]
                    # B = C + reverse(A), C palindrome in t ending at y2-b
                    c2 = 2 * b + palEndT[y2 - b + 1]
                    if c1 > ans:
                        ans = c1
                    if c2 > ans:
                        ans = c2
        return ans

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(N):
            if N <= 0:
                return 0
            digs = [ord(c) - 48 for c in str(N)]
            # free: dict (started, digit_sum, digit_product) -> count
            # counts prefixes already strictly smaller than N's prefix
            free = {}
            t_started, t_sm, t_pr = False, 0, 1  # tight (matching) prefix state
            for di in digs:
                nf = {}
                # diverge from the tight prefix by placing a smaller digit here
                for d in range(di):
                    if t_started or d:
                        k = (True, t_sm + d, t_pr * d)
                    else:
                        k = (False, 0, 1)
                    nf[k] = nf.get(k, 0) + 1
                # expand already-free states with any digit 0..9
                for (st, sm, pr), c in free.items():
                    if st:
                        for d in range(10):
                            k = (True, sm + d, pr * d)
                            nf[k] = nf.get(k, 0) + c
                    else:
                        for d in range(10):
                            k = (True, d, d) if d else (False, 0, 1)
                            nf[k] = nf.get(k, 0) + c
                free = nf
                # advance the tight prefix with N's own digit
                if t_started or di:
                    t_started, t_sm, t_pr = True, t_sm + di, t_pr * di
            total = 0
            for (st, sm, pr), c in free.items():
                if st and pr % sm == 0:
                    total += c
            # the fully tight path is N itself (N >= 1, so started)
            if t_started and t_pr % t_sm == 0:
                total += 1
            return total

        return count_up_to(r) - count_up_to(l - 1)

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 2:
            return max(nums)

        layers = {}

        def get(s, kk):
            if kk >= n:
                return nums[s]
            if kk == n - 1:
                return max(nums[s], nums[kk])
            return layers[kk][s]

        k = n - 2
        if k % 2 == 0:
            k -= 1
        while k >= 3:
            b, c = nums[k], nums[k + 1]
            g_shift = get(k + 1, k + 2)   # remove {s, k}, survivor k+1
            g_mid = get(k, k + 2)         # remove {s, k+1}, survivor k
            arr = [0] * k
            for s in range(k):
                a = nums[s]
                best = max(a, b) + g_shift
                t = max(a, c) + g_mid
                if t < best:
                    best = t
                t = max(b, c) + get(s, k + 2)   # remove {k, k+1}, survivor s stays
                if t < best:
                    best = t
                arr[s] = best
            layers[k] = arr
            k -= 2

        return min(max(nums[1], nums[2]) + get(0, 3),
                   max(nums[0], nums[1]) + get(2, 3),
                   max(nums[0], nums[2]) + get(1, 3))

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        from bisect import bisect_left
        L = 4 * side
        t = []
        for x, y in points:
            if y == 0:
                t.append(x)              # bottom edge
            elif x == side:
                t.append(side + y)       # right edge
            elif y == side:
                t.append(3 * side - x)   # top edge
            else:
                t.append(L - y)          # left edge
        t.sort()
        n = len(t)
        base = t + [v + L for v in t]
        T = base + [1 << 62]             # sentinel slot at index 2n
        m = 2 * n
        bl = bisect_left

        def check(d):
            # nxt[i] = first index with T value >= T[i] + d (sentinel = m)
            nxt = [bl(T, v + d) for v in base]
            nxt.append(m)
            P = range(n)
            for _ in range(k - 1):
                P = [nxt[x] for x in P]
            rem = L - d
            for a in range(n):
                if T[P[a]] - T[a] <= rem:   # wrap gap >= d
                    return True
            return False

        lo, hi = 0, L // k
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        T = sum(nums)
        if abs(k) > T:
            return -1
        S = 2 * T + 1
        full = (1 << S) - 1
        P = limit + 1
        # dp[j][p] = bitmask over sums (bit index = s + T), for NON-EMPTY subsequences
        # j = parity of chosen count; next element sign is + if j==0 else -
        # over[j] = bitmask of sums having some product > limit (needed for later 0-reset)
        dp = [[0] * P, [0] * P]
        over = [0, 0]

        for x in nums:
            ndp = [dp[0][:], dp[1][:]]
            nover = [over[0], over[1]]
            if x == 0:
                # taking a 0: parity flips, sum unchanged, product becomes 0
                for j in (0, 1):
                    agg = over[j]
                    row = dp[j]
                    for p in range(P):
                        if row[p]:
                            agg |= row[p]
                    if agg:
                        ndp[j ^ 1][0] |= agg
                # seed singleton [0]
                ndp[1][0] |= (1 << T)
            else:
                for j in (0, 1):
                    ov = over[j]
                    if ov:
                        if j == 0:
                            nover[j ^ 1] |= (ov << x) & full
                        else:
                            nover[j ^ 1] |= ov >> x
                    row = dp[j]
                    dst = ndp[j ^ 1]
                    if j == 0:
                        for p in range(P):
                            m = row[p]
                            if m:
                                q = p * x
                                sm = (m << x) & full
                                if q <= limit:
                                    dst[q] |= sm
                                else:
                                    nover[j ^ 1] |= sm
                    else:
                        for p in range(P):
                            m = row[p]
                            if m:
                                q = p * x
                                sm = m >> x
                                if q <= limit:
                                    dst[q] |= sm
                                else:
                                    nover[j ^ 1] |= sm
                # seed singleton [x]
                if x <= limit:
                    ndp[1][x] |= (1 << (T + x))
                else:
                    nover[1] |= (1 << (T + x))
            dp, over = ndp, nover

        probe = 1 << (T + k)
        for p in range(limit, -1, -1):
            if (dp[0][p] & probe) or (dp[1][p] & probe):
                return p
        return -1

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * n
        P[0] = nums[0]
        for i in range(1, n):
            P[i] = P[i - 1] + nums[i]
        cpre = [0] * (n + 1)
        for i in range(n):
            cpre[i + 1] = cpre[i] + cost[i]
        total_cost = cpre[n]

        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            r = i - 1
            base = P[r] * cpre[r + 1] + k * total_cost
            coef = P[r] + k
            best = None
            for m in range(i):
                cand = dp[m] - coef * cpre[m] + base
                if best is None or cand < best:
                    best = cand
            dp[i] = best
        return dp[n]

from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        la, lb, lc = len(A), len(B), len(C)
        n = len(s)

        def find_all(pat):
            res = []
            start = 0
            find = s.find
            while True:
                idx = find(pat, start)
                if idx == -1:
                    return res
                res.append(idx)
                start = idx + 1  # allow overlapping occurrences

        occA = find_all(A) if la else []
        occB = find_all(B) if lb else []
        occC = find_all(C) if lc else []

        if (la and not occA) or (lb and not occB) or (lc and not occC):
            return -1

        # If B is empty, it can match at any position 0..n
        j_list = range(n + 1) if lb == 0 else occB

        best = -1
        lower = la + lb + lc  # minimum achievable length

        for j in j_list:
            # latest A occurrence start i with i + la <= j
            if la == 0:
                i = j
            else:
                t = bisect_right(occA, j - la) - 1
                if t < 0:
                    continue
                i = occA[t]
            # earliest C occurrence start c with c >= j + lb
            k = j + lb
            if lc == 0:
                c = k
            else:
                t2 = bisect_left(occC, k)
                if t2 == len(occC):
                    continue
                c = occC[t2]
            cand = c + lc - i
            if best == -1 or cand < best:
                best = cand
                if best == lower:
                    break

        return best

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n <= k:
            return [0] * n

        children = [{}]
        cnt = [0]
        dep = [0]
        paths = []
        for w in words:
            cur = 0
            cnt[0] += 1
            path = [0]
            for ch in w:
                mp = children[cur]
                nxt = mp.get(ch)
                if nxt is None:
                    nxt = len(children)
                    mp[ch] = nxt
                    children.append({})
                    cnt.append(0)
                    dep.append(dep[cur] + 1)
                cur = nxt
                cnt[cur] += 1
                path.append(cur)
            paths.append(path)

        B = 0  # root: cnt == n >= k+1, depth 0
        ck = []
        for v in range(1, len(children)):
            c = cnt[v]
            if c > k:
                if dep[v] > B:
                    B = dep[v]
            elif c == k:
                ck.append((dep[v], v))

        if not ck:
            return [B] * n

        ck.sort(reverse=True)
        ck_ids = {v for _, v in ck}

        ans = [0] * n
        for i in range(n):
            pset = ck_ids.intersection(paths[i])
            off = -1
            for d, v in ck:
                if v not in pset:
                    off = d
                    break
            ans[i] = off if off > B else B
        return ans

from bisect import bisect_left

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        pos = {}
        for i, ch in enumerate(s):
            pos.setdefault(ch, []).append(i)
        chars = list(pos.keys())
        closures = set()
        for c in chars:
            L, R = pos[c][0], pos[c][-1]
            done = {c}
            while True:
                nl, nr = L, R
                for d in chars:
                    if d in done:
                        continue
                    lst = pos[d]
                    j = bisect_left(lst, L)
                    if j < len(lst) and lst[j] <= R:
                        done.add(d)
                        if lst[0] < nl:
                            nl = lst[0]
                        if lst[-1] > nr:
                            nr = lst[-1]
                if nl == L and nr == R:
                    break
                L, R = nl, nr
            if L != 0 or R != n - 1:
                closures.add((L, R))
        best = 0
        cl = list(closures)
        for L1, R1 in cl:
            if not any((L2, R2) != (L1, R1) and L2 >= L1 and R2 <= R1
                       for L2, R2 in cl):
                best += 1
        return best >= k

