from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    adj = [[False] * 26 for _ in range(26)]
    outd = [0] * 26
    ind = [0] * 26
    has = [False] * 26
    for i in range(1, n + 1):
        s = data[i].decode()
        u = ord(s[0]) - 65
        v = ord(s[1]) - 65
        adj[u][v] = True
        outd[u] += 1
        ind[v] += 1
        has[u] = True
        has[v] = True

    reach = [row[:] for row in adj]
    for k in range(26):
        rk = reach[k]
        for i in range(26):
            if reach[i][k]:
                ri = reach[i]
                for j in range(26):
                    if rk[j]:
                        ri[j] = True

    comp = [-1] * 26
    nc = 0
    for st in range(26):
        if has[st] and comp[st] == -1:
            comp[st] = nc
            dq = deque([st])
            while dq:
                u = dq.popleft()
                for w in range(26):
                    if comp[w] == -1 and (adj[u][w] or adj[w][u]):
                        comp[w] = nc
                        dq.append(w)
            nc += 1

    INF = 10 ** 9
    total = 0
    for c in range(nc):
        verts = [v for v in range(26) if comp[v] == c]
        m = len(verts)
        d = [outd[v] - ind[v] for v in verts]
        P = sum(x for x in d if x > 0)
        S, T = m, m + 1
        N = m + 2
        cap = [[0] * N for _ in range(N)]
        for i in range(m):
            if d[i] < 0:
                cap[S][i] = -d[i]
            elif d[i] > 0:
                cap[i][T] = d[i]
        for i in range(m):
            if d[i] < 0:
                for j in range(m):
                    if d[j] > 0 and reach[verts[i]][verts[j]]:
                        cap[i][j] = INF
        flow = 0
        while True:
            par = [-1] * N
            par[S] = S
            dq = deque([S])
            while dq:
                u = dq.popleft()
                if u == T:
                    break
                row = cap[u]
                for w in range(N):
                    if row[w] > 0 and par[w] == -1:
                        par[w] = u
                        dq.append(w)
            if par[T] == -1:
                break
            f = INF
            w = T
            while w != S:
                f = min(f, cap[par[w]][w])
                w = par[w]
            w = T
            while w != S:
                p = par[w]
                cap[p][w] -= f
                cap[w][p] += f
                w = p
            flow += f
        total += max(1, P - flow)
    print(total)

