def main():
    data = sys.stdin.buffer.read().split()
    H = int(data[0]); W = int(data[1]); K = int(data[2])
    rows = [data[3 + i] for i in range(H)]
    N = H * W
    free = bytearray(N)
    for i in range(H):
        r = rows[i]
        base = i * W
        for j in range(W):
            if r[j] == 46:
                free[base + j] = 1

    nbrs = [()] * N
    nbrs4 = [()] * N
    for i in range(H):
        base = i * W
        for j in range(W):
            c = base + j
            if free[c]:
                lst = []
                if i > 0 and free[c - W]: lst.append(c - W)
                if i + 1 < H and free[c + W]: lst.append(c + W)
                if j > 0 and free[c - 1]: lst.append(c - 1)
                if j + 1 < W and free[c + 1]: lst.append(c + 1)
                t = tuple(lst)
                nbrs[c] = t
                nbrs4[c] = t + (N,) * (4 - len(t))

    vis = bytearray(N + 1)
    vis[N] = 1  # dummy padding cell: always "visited"

    def dfs(pos, rem, vis=vis, nbrs=nbrs, nbrs4=nbrs4):
        total = 0
        if rem == 3:
            for u in nbrs[pos]:
                if not vis[u]:
                    vis[u] = 1
                    for q in nbrs[u]:
                        if not vis[q]:
                            a, b, c, d = nbrs4[q]
                            total += 4 - vis[a] - vis[b] - vis[c] - vis[d]
                    vis[u] = 0
        elif rem == 2:
            for u in nbrs[pos]:
                if not vis[u]:
                    a, b, c, d = nbrs4[u]
                    total += 4 - vis[a] - vis[b] - vis[c] - vis[d]
        else:
            for u in nbrs[pos]:
                if not vis[u]:
                    vis[u] = 1
                    total += dfs(u, rem - 1)
                    vis[u] = 0
        return total

    ans = 0
    if K == 1:
        for c in range(N):
            if free[c]:
                ans += len(nbrs[c])
    else:
        for c in range(N):
            if free[c]:
                vis[c] = 1
                ans += dfs(c, K)
                vis[c] = 0
    print(ans)

