import sys
from bisect import bisect_left, bisect_right

def query(coords, idxs, nxt, visited, lo_val, hi_val, cnt):
    lo = bisect_left(coords, lo_val)
    hi = bisect_right(coords, hi_val)
    if lo >= hi:
        return cnt
    i = lo
    j = i
    while nxt[j] != j:
        j = nxt[j]
    while nxt[i] != j:
        nxt[i], i = j, nxt[i]
    i = j
    while i < hi:
        h = idxs[i]
        if not visited[h]:
            visited[h] = 1
            cnt += 1
        nxt[i] = i + 1
        i += 1
        j = i
        while nxt[j] != j:
            j = nxt[j]
        while nxt[i] != j:
            nxt[i], i = j, nxt[i]
        i = j
    return cnt

