def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = list(map(int, data[1:1+N]))
    MOD = 998244353

    maxn = 2*N + 10
    fact = [1]*maxn
    for i in range(1, maxn):
        fact[i] = fact[i-1]*i % MOD
    inv_fact = [1]*maxn
    inv_fact[maxn-1] = pow(fact[maxn-1], MOD-2, MOD)
    for i in range(maxn-1, 0, -1):
        inv_fact[i-1] = inv_fact[i]*i % MOD
    inv = [0]*maxn
    inv[1] = 1
    for i in range(2, maxn):
        inv[i] = (MOD - MOD//i) * inv[MOD % i] % MOD

    def f(a, b):
        if a < 1 or a > b:
            return 0
        c = 2*b - a
        return a * inv[c] % MOD * fact[c] % MOD * inv_fact[b] % MOD * inv_fact[c-b] % MOD

    def SUM(l, r, m):
        if l > r:
            return 0
        return (f(l+1, m+1) - f(r+2, m+1)) % MOD

    ans = 0
    stack = []
    S = 0
    complete = True
    for idx in range(N):
        ai = A[idx]
        m = N - idx - 1
        if idx >= 1 and not stack:
            complete = False
            break
        if idx == 0:
            if ai >= 1 and m == 0:
                ans += 1
            ans += SUM(1, ai-1, m)
            if ai > 0:
                stack.append(ai)
            S = ai
        else:
            L = S - 1
            if L == 0 and m == 0 and ai >= 1:
                ans += 1
            ans += SUM(L if L >= 1 else 1, L + ai - 1, m)
            top = stack.pop() - 1
            if top > 0:
                stack.append(top)
            if ai > 0:
                stack.append(ai)
            S = S - 1 + ai

    if complete and S == 0:
        ans += 1
    print(ans % MOD)

