class Solution:
    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        answer = []
        for i in range(n - k + 1):
            window = nums[i:i + k]
            cnt = Counter(window)
            if len(cnt) <= x:
                answer.append(sum(window))
            else:
                top = sorted(cnt.items(), key=lambda p: (p[1], p[0]), reverse=True)[:x]
                answer.append(sum(c * v for v, c in top))
        return answer

