class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        beats = {'F': 'E', 'W': 'F', 'E': 'W'}  # key beats value
        moves = 'FWE'
        off = n
        size = 2 * n + 1

        # dp[li][k] = number of Bob sequences of length (rounds processed) ending in move `li`,
        # with score difference (Bob - Alice) = k - off
        dp = [[0] * size for _ in range(3)]
        a = s[0]
        for li in range(3):
            b = moves[li]
            if beats[b] == a:
                delta = 1
            elif beats[a] == b:
                delta = -1
            else:
                delta = 0
            dp[li][off + delta] = 1

        for i in range(1, n):
            a = s[i]
            deltas = []
            for li in range(3):
                b = moves[li]
                if beats[b] == a:
                    deltas.append(1)
                elif beats[a] == b:
                    deltas.append(-1)
                else:
                    deltas.append(0)

            ndp = []
            for li in range(3):
                j1 = (li + 1) % 3
                j2 = (li + 2) % 3
                # sum over previous last moves != current move (no two same in a row)
                total = [(x + y) % MOD for x, y in zip(dp[j1], dp[j2])]
                d = deltas[li]
                if d == 0:
                    ndp.append(total)
                elif d == 1:
                    ndp.append([0] + total[:-1])
                else:
                    ndp.append(total[1:] + [0])
            dp = ndp

        ans = 0
        for li in range(3):
            ans = (ans + sum(dp[li][off + 1:])) % MOD
        return ans

