class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        INF = float('inf')
        dist = [[INF] * m for _ in range(n)]
        dist[0][0] = 0
        heap = [(0, 0, 0)]
        while heap:
            t, i, j = heapq.heappop(heap)
            if t > dist[i][j]:
                continue
            if i == n - 1 and j == m - 1:
                return t
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                x, y = i + di, j + dj
                if 0 <= x < n and 0 <= y < m:
                    nt = max(t, moveTime[x][y]) + 1
                    if nt < dist[x][y]:
                        dist[x][y] = nt
                        heapq.heappush(heap, (nt, x, y))
        return dist[n - 1][m - 1]

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # run[i] = length of the maximal strictly increasing run ending at index i
        run = [1] * n
        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                run[i] = run[i - 1] + 1

        # Need indices a with a+2k-1 < n such that:
        #  - nums[a..a+k-1] strictly increasing  <=> run[a+k-1] >= k
        #  - nums[a+k..a+2k-1] strictly increasing <=> run[a+2k-1] >= k
        for a in range(n - 2 * k + 1):
            if run[a + k - 1] >= k and run[a + 2 * k - 1] >= k:
                return True
        return False

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        MAX = 10 ** 6
        spf = list(range(MAX + 1))

        # primes up to sqrt(MAX) = 1000
        lim = 1000
        is_comp = bytearray(lim + 1)
        primes = []
        for i in range(2, lim + 1):
            if not is_comp[i]:
                primes.append(i)
                for j in range(i * i, lim + 1, i):
                    is_comp[j] = True

        # write larger primes first so the smallest prime factor ends up last
        for p in reversed(primes):
            k = (MAX - p * p) // p + 1
            spf[p * p::p] = [p] * k

        n = len(nums)
        ops = 0
        limit = nums[-1]
        for i in range(n - 2, -1, -1):
            x = nums[i]
            if x <= limit:
                limit = x
                continue
            s = spf[x]
            if s <= limit:
                ops += 1
                limit = s
            else:
                return -1
        return ops

class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)
        for l, r in queries:
            diff[l] += 1
            diff[r + 1] -= 1

        cur = 0
        for i in range(n):
            cur += diff[i]
            if cur < nums[i]:
                return False
        return True

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # Binomial coefficients
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        # ops[c] = min operations to reduce c to 1
        ops = [0] * (L + 1)
        for c in range(2, L + 1):
            pc = bin(c).count('1')
            ops[c] = 1 + ops[pc]

        # Valid popcount values c: numbers x with popcount(x)=c are k-reducible
        valid = [c for c in range(1, L + 1) if ops[c] <= k - 1]

        ans = 0
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - 1 - i  # free positions after i
                for c in valid:
                    need = c - ones
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD
                ones += 1

        return ans % MOD

class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        ans = -1
        for i in range(n):
            s = 0
            for j in range(i, min(i + r, n)):
                s += nums[j]
                length = j - i + 1
                if length >= l and s > 0:
                    if ans == -1 or s < ans:
                        ans = s
        return ans

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for num in nums:
            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            h = (num + 1) // 2  # ceil(num/2)
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == INF:
                        continue
                    # no operation
                    if cur + num < ndp[a][b]:
                        ndp[a][b] = cur + num
                    # op1 only
                    if a + 1 <= op1 and cur + h < ndp[a + 1][b]:
                        ndp[a + 1][b] = cur + h
                    # op2 (and possibly op2 then op1)
                    if b + 1 <= op2 and num >= k:
                        v = num - k
                        if cur + v < ndp[a][b + 1]:
                            ndp[a][b + 1] = cur + v
                        if a + 1 <= op1:
                            v2 = (v + 1) // 2
                            if cur + v2 < ndp[a + 1][b + 1]:
                                ndp[a + 1][b + 1] = cur + v2
                    # op1 then op2
                    if a + 1 <= op1 and b + 1 <= op2 and h >= k:
                        v3 = h - k
                        if cur + v3 < ndp[a + 1][b + 1]:
                            ndp[a + 1][b + 1] = cur + v3
            dp = ndp
        return min(min(row) for row in dp)

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        parent_w = [0] * n
        order = []
        stack = [0]
        while stack:
            u = stack.pop()
            order.append(u)
            p = parent[u]
            for v, w in adj[u]:
                if v != p:
                    parent[v] = u
                    parent_w[v] = w
                    stack.append(v)

        # dp0[u]: edge to parent is KEPT -> u may keep at most k-1 child edges
        # dp1[u]: edge to parent is CUT   -> u may keep at most k child edges
        dp0 = [0] * n
        dp1 = [0] * n

        for u in reversed(order):
            total = 0
            gains = []
            p = parent[u]
            for v, w in adj[u]:
                if v == p:
                    continue
                total += dp1[v]
                gains.append(dp0[v] + w - dp1[v])
            gains.sort(reverse=True)

            s = 0
            for i in range(min(k, len(gains))):
                if gains[i] > 0:
                    s += gains[i]
                else:
                    break
            dp1[u] = total + s

            s0 = 0
            for i in range(min(k - 1, len(gains))):
                if gains[i] > 0:
                    s0 += gains[i]
                else:
                    break
            dp0[u] = total + s0

        return dp1[0]

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        total = sum(nums)
        left = 0
        ans = 0
        for i, v in enumerate(nums):
            right = total - left - v
            if v == 0:
                d = left - right
                if d == 0:
                    ans += 2
                elif abs(d) == 1:
                    ans += 1
            left += v
        return ans

class Solution:
    def possibleStringCount(self, word: str) -> int:
        # Each possible original is either word itself (no long press),
        # or word with exactly one run shortened. A run of length L offers
        # L-1 shortenings, which equals its count of adjacent equal pairs.
        return 1 + sum(1 for i in range(1, len(word)) if word[i] == word[i - 1])

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[c] = max points earned so far, currently in city c
        dp = [0] * n  # free choice of starting city => all zeros before day 0
        for i in range(k):
            ndp = [0] * n
            for c in range(n):
                best = dp[c] + stayScore[i][c]  # stay in city c
                for p in range(n):              # move from p to c
                    cand = dp[p] + travelScore[p][c]
                    if cand > best:
                        best = cand
                ndp[c] = best
            dp = ndp
        return max(dp)

