class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = float('inf')
        # min_pref[r] = minimum prefix sum P[i] with i % k == r (i < current)
        min_pref = [INF] * k
        min_pref[0] = 0  # P[0] = 0
        ans = -INF
        s = 0
        for i, x in enumerate(nums):
            s += x
            r = (i + 1) % k
            if min_pref[r] != INF:
                ans = max(ans, s - min_pref[r])
            if s < min_pref[r]:
                min_pref[r] = s
        return ans

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        cnt = Counter(nums)
        ans = None
        for x in nums:
            rem = total - x
            if rem % 2 != 0:
                continue
            s = rem // 2
            # sum element s must exist at a distinct index from x
            if s in cnt and (cnt[s] > 1 or s != x):
                if ans is None or x > ans:
                    ans = x
        return ans

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = set(map(tuple, points))
        n = len(points)
        best = -1
        for i in range(n):
            x1, y1 = points[i]
            for j in range(n):
                if i == j:
                    continue
                x2, y2 = points[j]
                if x1 < x2 and y1 < y2:
                    # candidate rectangle with corners (x1,y1),(x2,y2) as diagonal
                    if (x1, y2) in point_set and (x2, y1) in point_set:
                        ok = True
                        for k in range(n):
                            if k == i or k == j:
                                continue
                            px, py = points[k]
                            if (px, py) == (x1, y2) or (px, py) == (x2, y1):
                                continue  # these are the other two corners
                            if x1 <= px <= x2 and y1 <= py <= y2:
                                ok = False
                                break
                        if ok:
                            best = max(best, (x2 - x1) * (y2 - y1))
        return best

class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        INF = float('inf')
        dp = [INF] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == INF:
                continue
            x = 1 + bin(mask).count('1') * K
            for i in range(n):
                if not (mask >> i) & 1:
                    t = (strength[i] + x - 1) // x
                    nm = mask | (1 << i)
                    if dp[mask] + t < dp[nm]:
                        dp[nm] = dp[mask] + t
        return dp[(1 << n) - 1]

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # Operations only decrease values, so any value below k makes it impossible.
        if any(v < k for v in nums):
            return -1
        # Each valid operation reduces the count of distinct values > k by at most 1,
        # and collapsing from the largest distinct value downward achieves exactly one per step.
        return len({v for v in nums if v > k})

