class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_index = events[0][0]
        best_time = events[0][1]
        for i in range(1, len(events)):
            duration = events[i][1] - events[i - 1][1]
            if duration > best_time or (duration == best_time and events[i][0] < best_index):
                best_time = duration
                best_index = events[i][0]
        return best_index

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        # Find the longest suffix with all distinct elements.
        # If that suffix starts at index i, we must remove the first i elements,
        # which takes ceil(i / 3) operations.
        seen = set()
        i = len(nums)
        for j in range(len(nums) - 1, -1, -1):
            if nums[j] in seen:
                break
            seen.add(nums[j])
            i = j
        return (i + 2) // 3

class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        last = float('-inf')
        count = 0
        for x in nums:
            cand = max(last + 1, x - k)
            if cand <= x + k:
                count += 1
                last = cand
        return count

