class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])
        prev = [0] * 16
        for i in range(m):
            cur = [0] * 16
            for j in range(n):
                if i == 0 and j == 0:
                    cur[grid[0][0]] = 1
                    continue
                x = grid[i][j]
                for v in range(16):
                    s = 0
                    if i > 0:
                        s += prev[v ^ x]
                    if j > 0:
                        s += cur[v ^ x]
                    cur[v] = s % MOD
            prev = cur
        return prev[k] % MOD

class Solution:
    def calculateScore(self, s: str) -> int:
        # stacks[k] holds unmarked indices with character k, in increasing order.
        # At index i with char c (mirror m = 25 - c), the closest unmarked j
        # with s[j] == mirror char is the top of stacks[m].
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            m = 25 - c
            if stacks[m]:
                j = stacks[m].pop()  # mark j and i implicitly
                score += i - j
            else:
                stacks[c].append(i)  # i stays unmarked, available for future
        return score

