class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        def can_cut(intervals: List[List[int]]) -> bool:
            intervals.sort()
            groups = 0
            cur_end = -1
            for start, end in intervals:
                if start >= cur_end:
                    groups += 1
                    cur_end = end
                else:
                    cur_end = max(cur_end, end)
                if groups >= 3:
                    return True
            return False

        return (can_cut([[r[0], r[2]] for r in rectangles]) or
                can_cut([[r[1], r[3]] for r in rectangles]))

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        from collections import deque, defaultdict

        # BFS on day-1 graph from initialCurrency: max amount of each currency after day 1
        g1 = defaultdict(list)
        for (u, v), r in zip(pairs1, rates1):
            g1[u].append((v, r))
            g1[v].append((u, 1.0 / r))
        day1 = {initialCurrency: 1.0}
        dq = deque([initialCurrency])
        while dq:
            cur = dq.popleft()
            for nxt, r in g1[cur]:
                if nxt not in day1:
                    day1[nxt] = day1[cur] * r
                    dq.append(nxt)

        # BFS on reversed day-2 graph from initialCurrency:
        # back[X] = multiplier converting X -> initialCurrency in graph 2
        g2 = defaultdict(list)
        for (u, v), r in zip(pairs2, rates2):
            g2[v].append((u, r))        # corresponds to original u -> v
            g2[u].append((v, 1.0 / r))  # corresponds to original v -> u
        back = {initialCurrency: 1.0}
        dq = deque([initialCurrency])
        while dq:
            cur = dq.popleft()
            for nxt, r in g2[cur]:
                if nxt not in back:
                    back[nxt] = back[cur] * r
                    dq.append(nxt)

        ans = 1.0
        for cur, amt in day1.items():
            if cur in back:
                ans = max(ans, amt * back[cur])
        return ans

