class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        n = len(coins)
        prefix = [0] * (n + 1)
        for i, (l, r, c) in enumerate(coins):
            prefix[i + 1] = prefix[i] + (r - l + 1) * c

        ans = 0

        # Case 1: window starts exactly at l_i -> [l_i, l_i + k - 1]
        j = 0
        for i in range(n):
            if j < i:
                j = i
            end = coins[i][0] + k - 1
            while j < n and coins[j][1] <= end:
                j += 1
            total = prefix[j] - prefix[i]
            if j < n and coins[j][0] <= end:
                total += (end - coins[j][0] + 1) * coins[j][2]
            if total > ans:
                ans = total

        # Case 2: window ends exactly at r_i -> [r_i - k + 1, r_i]
        j = 0
        for i in range(n):
            start = coins[i][1] - k + 1
            while j < n and coins[j][0] < start:
                j += 1
            total = prefix[i + 1] - prefix[j]
            if j > 0 and coins[j - 1][1] >= start:
                total += (coins[j - 1][1] - start + 1) * coins[j - 1][2]
            if total > ans:
                ans = total

        return ans

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Compute lengths of maximal runs
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def ok(m):
            if m == 1:
                # Must become fully alternating; count mismatches vs both phases
                c1 = sum(1 for k in range(n) if (ord(s[k]) - 48) != (k & 1))
                return min(c1, n - c1) <= numOps
            # For m >= 2, each run of length L needs floor(L / (m+1)) flips
            return sum(L // (m + 1) for L in runs) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

