class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        S = [v for v in nums if v <= T]
        res = len(nums) - len(S)          # values > threshold are isolated nodes
        if not S:
            return res
        S.sort()
        if S[0] == 1:                     # 1 connects to every value <= threshold
            return res + 1
        parent = list(range(T + 1))
        sz = [1] * (T + 1)
        rep = [0] * (T + 1)
        for v in S:
            for m in range(v, T + 1, v):
                r = rep[m]
                if r == 0:
                    rep[m] = v
                else:
                    a = r
                    while parent[a] != a:
                        parent[a] = parent[parent[a]]
                        a = parent[a]
                    b = v
                    while parent[b] != b:
                        parent[b] = parent[parent[b]]
                        b = parent[b]
                    if a != b:
                        if sz[a] < sz[b]:
                            a, b = b, a
                        parent[b] = a
                        sz[a] += sz[b]
        roots = set()
        for v in S:
            x = v
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            roots.add(x)
        return res + len(roots)

