                    s += a * pr
            sb = s.to_bytes(SL * n, 'little')
            out.append([int.from_bytes(sb[SL * k:SL * k + SL], 'little') % p for k in range(n)])
        return out

    result = None
    base = [row[:] for row in A]
    e = p
    while e:
        if e & 1:
            result = base if result is None else mat_mul(result, base)
        e >>= 1
        if e:
            base = mat_mul(base, base)
    M = result

    K = 0
    for i in range(n):
        for j in range(n):
            if A[i][j] == 0:
                K += 1
                if i == j:
                    for t in range(n):
                        M[t][j] = (M[t][j] + A[t][j]) % p
                        M[j][t] = (M[j][t] + A[j][t]) % p
                elif p == 3:
                    M[i][j] = (M[i][j] + A[j][i]) % p

    if K & 1:
        M = [[(-x) % p for x in row] for row in M]

    sys.stdout.write('\n'.join(' '.join(map(str, r)) for r in M) + '\n')

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); Q = int(data[1])
    Ks = list(map(int, data[2:2 + Q]))
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    dp[0][0] = 1
    for r in range(N - 1):
        dpr = dp[r]
        for c in range(N - 1):
            v = dpr[c]
            if not v:
                continue
            for a in range(2, N - r + 1):
                dpr2 = dp[r + a]
                for b in range(2, N - c + 1):
                    dpr2[c + b] |= v << (a * b)
    ach = 0
    for row in dp:
        for x in row:
            ach |= x
    N2 = N * N
    print("\n".join("Yes" if (ach >> (N2 - K)) & 1 else "No" for K in Ks))

main()

class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        maxc = max(cnt)
        best = len(s)
        for m in range(1, maxc + 1):
            if best == 0:
                break
            c0 = cnt[0]
            if c0 > m:
                dp0, dp1, spm = c0, c0 - m, c0 - m
            else:
                dp0, dp1, spm = c0, m - c0, 0
            sp0 = c0
            for i in range(1, 26):
                c = cnt[i]
                if c < m:
                    d = m - c
                    cm = d
                else:
                    d = 0
                    cm = c - m
                new0 = c + (dp0 if dp0 < dp1 else dp1)
                a = dp0 - (sp0 if sp0 < d else d)
                b = dp1 - (spm if spm < d else d)
                new1 = cm + (a if a < b else b)
                dp0, dp1 = new0, new1
                sp0 = c
                spm = c - m if c > m else 0
            if dp0 < best:
                best = dp0
            if dp1 < best:
                best = dp1
        return best
